// EQUALIZER
function randomBetween(range) {
    var min = range[0]
        , max = range[1];
    if (min < 0) {
        return min + Math.random() * (Math.abs(min) + max);
    } else {
        return min + Math.random() * max;
    }
}

$.fn.equalizerAnimation = function (speed, barsHeight) {
    var $equalizer = $(this);
    setInterval(function () {
        $equalizer.find('span').each(function (i) {
            $(this).css({
                height: randomBetween(barsHeight[i]) + 'px'
            });
        });
    }, speed);
    $equalizer.on('click', function () {
        $equalizer.toggleClass('paused');
    });
}
    ;

var barsHeight = [[2, 13], [5, 22], [17, 8], [4, 18], [11, 3]];
$('.equalizer').equalizerAnimation(180, barsHeight);

// BACK BUTTON RELOAD
window.onpageshow = function (event) {
    if (event.persisted) {
        window.location.reload()
    }
}
    ;

// PAGE TRANSITION
$('body a').on('click', function (e) {
    if ($(this).data('horizontal-timeline') != null || $(this).data('horizontal-timeline') != undefined || $(this).hasClass('fas')) {
        return;
    }

    var target = $(this).attr('target');
    var fancybox = $(this).data('fancybox');
    var url = this.getAttribute("href");
    if (target != '_blank' && typeof fancybox == 'undefined' && url.indexOf('#') && url.indexOf('javascript:void(0);') < 0) {

        e.preventDefault();
        var url = this.getAttribute("href");

        if (url.indexOf('#' && 'javascript:void(0);') != -1) {
            var hash = url.substring(url.indexOf('#'));

            if ($('body ' + hash).length != 0) {
                $('.page-transition').removeClass("active");
                $(".hamburger").toggleClass("open");
                $("body").toggleClass("overflow");
                $(".navigation-menu").removeClass("active");
                $(".navigation-menu .inner ul").css("transition-delay", "0s");
                $(".navigation-menu .inner blockquote").css("transition-delay", "0s");
                $(".navigation-menu .bg-layers span").css("transition-delay", "0.3s");

                $('html, body').animate({
                    scrollTop: $(hash).offset().top
                }, 1000);
            }
        } else {

            $('.page-transition').toggleClass("active");
            setTimeout(function () {
                window.location = url;
            }, 1000);
        }
    }
});
