$(document).on('click', '.all-news-left .item-news-left', function (e) {
    e.preventDefault();
    let oldThisNews = this;
    let clickedIndexNews = $(this).index();
    $('.all-news-left .item-news-left').removeClass('active-news');
    $('.featured-news-item').hide().promise().done(function () {
        $('.featured-news-item').not('.featured-news-item:eq("' + clickedIndexNews + '")').hide().promise().done(function () {
            if (!$('.featured-news-item').is(':visible')) {
                $(oldThisNews).addClass('active-news');
                $('.featured-news-item:eq("' + clickedIndexNews + '")').show().promise().done();
            }
        });
    });
});

$(document).on('focus', '.form-ele input,.form-ele textarea', function () {
    if ($(this).val() != '') {
        $(this).siblings('span').addClass('focused-input');
    } else {
        $(this).siblings('span').removeClass('focused-input');
    }
});

$(document).on('blur', '.form-ele input,.form-ele textarea', function () {
    if ($(this).val() != '') {
        $(this).siblings('span').addClass('focused-input');
    } else {
        $(this).siblings('span').removeClass('focused-input');
    }
});

$(document).ready(function () {

    $('.events-content li ul').each(function () {
        if ($(this).children('li').length > 1) {
            $(this).css('list-style', 'circle');
        } else {
            $(this).css('list-style', 'none');
        }
    });

    $('.offerItemTitle').click(function () {

        $(this).parents('.offerslide').children('.offerItem').removeClass('active');
        $(this).parents('.offerslide').children('.offerItem').children('.offerItemTitle').removeClass('hide');
        $(this).parent('.offerItem').addClass('active');
        $(this).addClass('hide');

    });

    $(window).scroll(function () {

        if ($(this).scrollTop() > 500) {
            $('#goTopBtn').fadeIn();
        } else {
            $('#goTopBtn').fadeOut();
        }
    });

    $('#goTopBtn').click(function () {
        $("html, body").animate({
            scrollTop: 0
        }, 1000);
    });

    $(function () {
        $('.scroll-down').click(function (e) {
            e.preventDefault();
            $('html, body').animate({
                scrollTop: $(this).parents('header').next('section').offset().top
            }, 'slow');
            return false;
        });
    });

    $(window).scroll(function () {
        var element = $("#mobile-menu-btn-open");
        var scrollPosition = $(window).scrollTop();
        var windowHeight = $(window).height();

        // Adjust this value to control when the element appears
        var triggerHeight = windowHeight;

        if (scrollPosition >= triggerHeight) {
            element.fadeIn();
        } else {
            element.fadeOut();
        }
    });

    //$('.mobile-menu-btn').on('click', function (e) {
    //    if ($(".site-navigation").hasClass("active")) {
    //        $("body").toggleClass("overflow");
    //        $(".site-navigation").removeClass("active");
    //        $(".site-navigation").css("transition-delay", "0.5s");
    //        $(".site-navigation .layer").css("transition-delay", "0.3s");
    //        $(".site-navigation .inner").css("transition-delay", "0s");
    //        $(this).children('i').removeClass('fa-bars').addClass('fa-times');
    //    } else {
    //        $(".site-navigation").addClass('active');
    //        $("body").toggleClass("overflow");
    //        $(".site-navigation.active").css("transition-delay", "0s");
    //        $(".site-navigation.active .layer").css("transition-delay", "0.2s");
    //        $(".site-navigation.active .inner").css("transition-delay", "0.7s");
    //        $(this).children('i').removeClass('fa-times').addClass('fa-bars');
    //    }
    //    $(this).toggleClass("is-opened-navi");
    //});

    $('.mobile-menu-btn').on('click', function (e) {
        if ($(".site-navigation").hasClass("active")) {
            $("body").toggleClass("overflow");
            $(".site-navigation").removeClass("active");
            $(".site-navigation").css("transition-delay", "0.5s");
            $(".site-navigation .layer").css("transition-delay", "0.3s");
            $(".site-navigation .inner").css("transition-delay", "0s");
            $('#mobile-menu-btn-open').show();
            $("#mobile-menu-btn-close").hide();

        } else {
            $(".site-navigation").addClass('active');
            $("body").toggleClass("overflow");
            $(".site-navigation.active").css("transition-delay", "0s");
            $(".site-navigation.active .layer").css("transition-delay", "0.2s");
            $(".site-navigation.active .inner").css("transition-delay", "0.7s");
            $('#mobile-menu-btn-open').hide();
            $("#mobile-menu-btn-close").show();

        }
        $(this).toggleClass("is-opened-navi");
    });

    $('body').on('click', '.scroll-down', function () {
        $('html, body').animate({
            scrollTop: $(window).scrollTop() + $(window).height()
        }, 800);
    });

});

