function initAccreditationSlider() {
    var swiperAcc = new Swiper(".accreditations-swiper", {
        effect: "coverflow",
        grabCursor: true,
        centeredSlides: false,
        loop: true,
        slidesPerView: 3,
        spaceBetween: 30,
        coverflowEffect: {
            rotate: 50,
            stretch: 0,
            depth: 100,
            modifier: 1,
            slideShadows: true,
        },
        breakpoints: {
            768: {
                centeredSlides: false,
                slidesPerView: 3,
                spaceBetween: 30,
            },
            640: {
                slidesPerView: 2,
                spaceBetween: 20,
            },
            320: {
                centeredSlides: true,
                slidesPerView: 1,
                spaceBetween: 0,
            }
        },
        navigation: {
            nextEl: ".swiper-button-next-uniqe5",
            prevEl: ".swiper-button-prev-uniqe5",
        }
    });
}

function initManagmentTeamSlider() {
    // Slider For Team Images Thumbnails (About us)
    var teamSwiperThumb = new Swiper(".teamSwiperThumb", {
        spaceBetween: 18,
        slidesPerView: 4,
        centerInsufficientSlides: true,
        freeMode: true,
        watchSlidesProgress: true,
        navigation: {
            nextEl: ".swiper-button-next-thumb",
            prevEl: ".swiper-button-prev-thumb",
        },
        breakpoints: {
            768: {
                slidesPerView: 4,
                spaceBetween: 18,
            },
            640: {
                slidesPerView: 3,
                spaceBetween: 20,
            },
            320: {
                slidesPerView: 2,
                spaceBetween: 20,
            },
        },
    });

    // Slider For Team (About us)
    var teamSwiperMain = new Swiper(".teamSwiperMain", {
        spaceBetween: 10,
        navigation: {
            nextEl: ".swiper-button-next-inner",
            prevEl: ".swiper-button-prev-inner",
        },
        thumbs: {
            swiper: teamSwiperThumb,
        },
    });
}
